use v5.42;
use strict;
use warnings;
use JSON::PP 'decode_json';
use Digest::SHA 'sha256_hex';
use lib 'bench/lib';
use Wump::BenchMatrix qw(load_capture compare);
my $dir=shift // 'bench';
sub contents ($path) {open my $in,'<',$path or die "$path: $!"; local $/; my $text=<$in>; close $in or die $!; return $text}
my $before=load_capture("$dir/operation-matrix-select-before.json");
my $after=load_capture("$dir/operation-matrix-select-current.json");
my $anchor=load_capture('bench/operation-matrix-callee-baseline.json');
my $fixture=sha256_hex(join '', map {contents($_)} qw(bench/matrix.pl bench/matrix-worker.pl bench/matrix-worker.go bench/lib/Wump/BenchMatrix.pm));
for my $c ($before,$after) {
	my @s=map {@{$_->{samples}}} @{$c->{cells}};
	@s==770 && grep($_->{status} eq 'ok',@s)==640 && !$c->{source}{dirty}
		&& $c->{source}{fixture_sha256} eq $fixture or die 'invalid matrix provenance/completion';
}
for my $spec ([$before,'check'],[$anchor,'anchor-check']) {
	my ($failed,$text)=compare($spec->[0],$after,10);
	$text eq contents("$dir/operation-matrix-select-$spec->[1].txt") or die 'incorrect saved comparison';
	my $failures=()=$text=~/^FAIL /mg;
	print "ok - $spec->[1] saved exactly; gate status $failed ($failures failed metrics)\n";
}
my $m=decode_json(contents("$dir/native-select-machine.json"));
$m->{source_revision} eq $after->{source}{revision} && $m->{source_revision} eq $before->{source}{revision} or die 'wrong harness source';
for my $path (keys %{$m->{sha256}}) {
	my $text;
	if ($path =~ m{^/}) {$text=contents($path)}
	else {open my $in,'-|','git','show',"$m->{source_revision}:$path" or die $!; $text=do {local $/; <$in>}; close $in or die 'source unavailable'}
	sha256_hex($text) eq $m->{sha256}{$path} or die "changed source/binary/archive: $path";
}
$m->{binaries}{before}{sha256} eq $before->{binaries}{wump}{sha256}
	&& $m->{binaries}{current}{sha256} eq $after->{binaries}{wump}{sha256}
	or die 'wrong paired binaries';
print "ok - all 1540 matrix samples, source/binary/archive hashes and exact gate reports verified\n";
